adapter.sqlQuery:
WITH AppAccess AS ( SELECT CubeName, 'Command Programming' as Module, CASE WHEN CHARINDEX('_', FundsCenter) > 0 THEN RIGHT(FundsCenter, CHARINDEX('_', REVERSE(FundsCenter)) - 1) ELSE NULL END AS FundsCenter, UserName, UserDescription, UserIsEnabled, UserEmail, UserOrg, UserRole, GroupDescription FROM ( SELECT DISTINCT
U.Name AS UserName, U.Description AS UserDescription, U.IsEnabled AS UserIsEnabled, U.Email AS UserEmail,
-- User Organization CASE WHEN U.Description LIKE '%TRADOC%' THEN 'TRADOC' WHEN U.Description LIKE '%FORSCOM%' THEN 'FORSCOM' WHEN U.Description LIKE '%AFC%' THEN 'AFC' WHEN U.Description LIKE '%AMC%' THEN 'AMC' WHEN U.Description LIKE '%HQDA%' THEN 'HQDA' WHEN U.Description LIKE '%ARCYBER%' THEN 'ARCYBER' WHEN U.Description LIKE '%NGB%' THEN 'NGB' WHEN U.Description LIKE '%USMA%' THEN 'USMA' WHEN U.Description LIKE '%USARPAC%' THEN 'USARPAC' WHEN U.Description LIKE '%USASMDC%' THEN 'USASMDC' WHEN U.Description LIKE '%INSCOM%' THEN 'INSCOM' WHEN U.Description LIKE '%USAREUR_AF%' THEN 'USAREUR_AF' ELSE 'OTHER' END AS UserOrg, -- FundsCenter CASE WHEN G.Name LIKE '%[_]PGM[_]%' THEN G.Name ELSE NULL END AS FundsCenter, --User Role CASE WHEN G.Name LIKE '%[_]VA[_]%' THEN 'Validator' WHEN G.Name LIKE '%[_]CR[_]%' THEN 'Creator' WHEN G.Name LIKE '%[_]PR[_]%' THEN 'Prioritizer' WHEN G.Name LIKE '%[_]MG[_]%' THEN 'Manager' WHEN G.Name LIKE '%[_]AP[_]%' THEN 'Approver' WHEN G.Name LIKE '%[_]RR[_]%' THEN 'Rollover' ELSE 'OTHER' END AS UserRole, --CubeName CASE WHEN G.Name LIKE '%TRADOC%' THEN 'TRADOC' WHEN G.Name LIKE '%FORSCOM%' THEN 'FORSCOM' WHEN G.Name LIKE '%AFC%' THEN 'AFC' WHEN G.Name LIKE '%AMC%' THEN 'AMC' WHEN G.Name LIKE '%HQDA%' THEN 'HQDA' WHEN G.Name LIKE '%ARCYBER%' THEN 'ARCYBER' WHEN G.Name LIKE '%NGB%' THEN 'NGB' WHEN G.Name LIKE '%USMA%' THEN 'USMA' WHEN G.Name LIKE '%USARPAC%' THEN 'USARPAC' WHEN G.Name LIKE '%USASMDC%' THEN 'USASMDC' WHEN G.Name LIKE '%INSCOM%' THEN 'INSCOM' WHEN G.Name LIKE '%USAREUR_AF%' THEN 'USAREUR_AF' ELSE 'OTHER' END AS CubeName, G.Description AS GroupDescription FROM dbo.SecGroupChild AS GU INNER JOIN dbo.SecGroup AS G ON GU.GroupKey = G.UniqueID INNER JOIN dbo.SecUser AS U ON GU.ChildKey = U.UniqueID WHERE GU.ChildIsAUser = 1 AND G.Name NOT LIKE '%OpenApplication%' AND G.Name LIKE '%[_]PGM[_]%' ) AS sqry ) SELECT * FROM AppAccess;

